#!/bin/sh
# SCHEM-NL-08 capture driver, generated by tools/golden/authoring/schem_cases.py (m8-schematic design D16).
# Each run is a fresh xschem netlist run; the driver prints its exit status and exits with
# the last non-zero one.
status=0
mkdir -p out
run() {
  label=$1; shift
  echo "== $label"; echo "== $label" >&2
  "$@"; rc=$?
  echo "== $label: exit $rc"
  if [ "$rc" -ne 0 ]; then status=$rc; fi
}
run dc_hbt_13g2 xschem -q -x -r --rcfile /work/input/xschemrc -n -s -o /work/out /pdk/ihp-sg13g2/libs.tech/xschem/sg13g2_tests/dc_hbt_13g2.sch
run ac_mim_cap xschem -q -x -r --rcfile /work/input/xschemrc -n -s -o /work/out /pdk/ihp-sg13g2/libs.tech/xschem/sg13g2_tests/ac_mim_cap.sch
exit "$status"
